float sphere(vec3 pos, float radius) {
    return length(pos) - radius;
}

vec3 normal(vec3 pos, float radius) {
    return normalize(pos);
}

vec3 lighting(vec3 normal, vec3 lightDir, vec3 lightColor, float ambientIntensity) {
    float diffuse = max(dot(normal, lightDir), 0.0);
    return (lightColor * diffuse) + (lightColor * ambientIntensity);
}

bool rayIntersect
(

 vec3 O, 
 vec3 D, 

 vec3 C, 
 float R, 
 out float AO, 
 out float BO  
)
{
 vec3 L = C - O;
 float DT = dot (L, D);
 float R2 = R * R;

 float CT2 = dot(L,L) - DT*DT;

 if (CT2 > R2)
 return false;

 float AT = sqrt(R2 - CT2);
 float BT = AT;

 AO = DT - AT;
 BO = DT + BT;
 return true;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{

    vec2 uv = fragCoord/iResolution.xy;

    vec2 p = -1.0 + 2.0 * uv;
    p.x *= iResolution.x/iResolution.y;


    vec3 rayOrigin = vec3(0.0, 0.0, 2.0);

    vec3 rayDirection = normalize(vec3(p, -2.0));


    vec3 sphereCenter = vec3(0.0, 0.0, 0.0);
    float sphereRadius = 0.7;   

    float A0, B0;


    if(rayIntersect(rayOrigin, rayDirection, sphereCenter, sphereRadius ,A0, B0)) { 
          vec3 normalVector = normal(rayOrigin + rayDirection*A0 - sphereCenter, sphereRadius); 

          vec3 lightDirection = normalize(vec3(3.0 * cos(iTime), 3.0 * sin(iTime), 1.0)); 
          vec3 lightColor = vec3(1.0, 1.0, 1.0); 
          float ambientIntensity = 0.0; 

          vec3 finalColor = lighting(normalVector, lightDirection, lightColor, ambientIntensity);

          fragColor = vec4(finalColor, 1.0);
          return;
    }


    fragColor = vec4(0.0,0.0,0.0,1.0);
}
